/* Carrega produtos do Firestore (se configurado). Na primeira vez, semeia o
   banco com o catálogo padrão. Depois disso, mantém tudo sincronizado em
   tempo real — quando o admin edita um produto, o site atualiza sozinho. */
async function initProductsSync(){
  if(!firebaseReady){ return; }
  try{
    const snap = await fbDb.collection('products').limit(1).get();
    if(snap.empty){
      const batch = fbDb.batch();
      DEFAULT_PRODUCTS.forEach(p=>{
        batch.set(fbDb.collection('products').doc(p.id), p);
      });
      await batch.commit();
    }
  } catch(e){ console.error('Erro ao semear produtos:', e); }

  fbDb.collection('products').onSnapshot(snapshot=>{
    const list = [];
    snapshot.forEach(doc=> list.push(doc.data()));
    if(list.length){
      PRODUCTS = list;
      refreshProductViews();
    }
  }, err=> console.error('Erro ao sincronizar produtos:', err));
}

