/* ================= SPOOL SVG (signature visual) ================= */
function spoolSVG(hex, size=100){
  return `<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
    <circle cx="50" cy="50" r="46" fill="none" stroke="${hex}" stroke-width="3" opacity="0.25"/>
    <circle cx="50" cy="50" r="34" fill="none" stroke="${hex}" stroke-width="9" stroke-dasharray="2 3" opacity="0.9"/>
    <circle cx="50" cy="50" r="20" fill="#0a0d0b" stroke="${hex}" stroke-width="2"/>
    <circle cx="50" cy="50" r="6" fill="none" stroke="var(--text-dim)" stroke-width="2"/>
  </svg>`;
}

