/* ================= RENDER: product card ================= */
function productCard(p){
  const hex = COLORS[p.colors[0]] || '#8a8f89';
  const thumbContent = p.photo
    ? `<img src="${p.photo}" alt="${p.name}" style="width:100%;height:100%;object-fit:contain;">`
    : `<div class="spool">${spoolSVG(hex)}</div>`;
  return `<div class="prod-card bracket" data-id="${p.id}">
    ${p.oldPrice ? '<div class="badge-sale">OFERTA</div>' : ''}
    <div class="thumb">${thumbContent}</div>
    <div class="prod-info">
      <div class="prod-type">${p.type}</div>
      <div class="prod-name">${p.name}</div>
      <div class="prod-meta">${p.weight}</div>
      <div class="prod-rating">★ ${p.rating.toFixed(1)}/5</div>
      <div class="prod-price-row">
        ${p.oldPrice ? `<span class="prod-price-old mono">${fmt(p.oldPrice)}</span>` : ''}
        <span class="prod-price">${fmt(p.price)}</span>
      </div>
      <div class="prod-actions">
        <button class="btn btn-outline add-quick" data-id="${p.id}">+ Carrinho</button>
        <button class="btn btn-gold view-prod" data-id="${p.id}">Ver</button>
      </div>
    </div>
  </div>`;
}

function wireProductCards(container){
  container.querySelectorAll('.view-prod, .prod-card .thumb, .prod-card .prod-name').forEach(el=>{
    el.addEventListener('click',(e)=>{
      const card = e.target.closest('.prod-card');
      if(card) location.hash = '#produto/'+card.dataset.id;
    });
  });
  container.querySelectorAll('.add-quick').forEach(el=>{
    el.addEventListener('click',(e)=>{
      e.stopPropagation();
      const p = PRODUCTS.find(x=>x.id===el.dataset.id);
      addToCart(p, p.colors[0], 1);
    });
  });
}

let featuredPageIdx = 0;
let featuredTimer = null;

function chunk(arr, size){
  const out = [];
  for(let i=0;i<arr.length;i+=size) out.push(arr.slice(i,i+size));
  return out;
}

function renderFeatured(){
  const grid = document.getElementById('featuredGrid');
  const dotsWrap = document.getElementById('featuredDots');
  const offers = PRODUCTS.filter(p=>p.oldPrice);
  const pool = offers.length ? offers : PRODUCTS;
  const pages = chunk(pool, 4);

  function renderDots(activeIdx){
    dotsWrap.innerHTML = pages.map((_,i)=>`<div class="hero-dot ${i===activeIdx?'active':''}" data-i="${i}"></div>`).join('');
    dotsWrap.querySelectorAll('.hero-dot').forEach(d=>d.addEventListener('click',()=>{
      featuredPageIdx = +d.dataset.i;
      paintPage(featuredPageIdx);
      if(featuredTimer) clearInterval(featuredTimer);
      featuredTimer = setInterval(()=>{
        featuredPageIdx = (featuredPageIdx + 1) % pages.length;
        paintPage(featuredPageIdx);
      }, 15000);
    }));
  }

  function paintPage(idx){
    grid.style.opacity = '0';
    setTimeout(()=>{
      grid.innerHTML = pages[idx].map(productCard).join('');
      wireProductCards(grid);
      grid.style.opacity = '1';
      renderDots(idx);
    }, 200);
  }

  grid.style.transition = 'opacity .2s ease';
  paintPage(featuredPageIdx % pages.length);

  if(featuredTimer) clearInterval(featuredTimer);
  if(pages.length > 1){
    featuredTimer = setInterval(()=>{
      featuredPageIdx = (featuredPageIdx + 1) % pages.length;
      paintPage(featuredPageIdx);
    }, 15000);
  }
}

function renderOfertas(){
  const grid = document.getElementById('ofertasGrid');
  const items = PRODUCTS.filter(p=>p.oldPrice);
  grid.innerHTML = items.map(productCard).join('');
  wireProductCards(grid);
}

function renderAllProducts(filterCat){
  const grid = document.getElementById('allProdGrid');
  const heading = document.getElementById('prodListHeading');
  const bc = document.getElementById('prodListTitle');
  let items = PRODUCTS;
  if(filterCat && filterCat!=='ofertas'){
    items = PRODUCTS.filter(p=>p.type===filterCat);
    const catObj = CATEGORIES.find(c=>c.id===filterCat);
    heading.textContent = catObj ? catObj.name : 'Filamentos';
    bc.textContent = catObj ? catObj.name : 'Filamentos';
  } else if(filterCat==='ofertas'){
    items = PRODUCTS.filter(p=>p.oldPrice);
    heading.textContent = 'Ofertas';
    bc.textContent = 'Ofertas';
  } else {
    heading.textContent = 'Todos os filamentos';
    bc.textContent = 'Filamentos';
  }
  grid.innerHTML = items.length ? items.map(productCard).join('') : '<p style="color:var(--text-dim);grid-column:1/-1;">Nenhum produto encontrado nesta categoria.</p>';
  wireProductCards(grid);
}

/* ================= RENDER: product detail ================= */
function renderProductDetail(id){
  const p = PRODUCTS.find(x=>x.id===id);
  if(!p){ location.hash='#produtos'; return; }
  currentProduct = p; currentColor = p.colors[0]; currentQty = 1;

  document.getElementById('pdBreadcrumb').textContent = p.name;
  document.getElementById('pdType').textContent = p.type.toUpperCase();
  document.getElementById('pdName').textContent = p.name;
  document.getElementById('pdRating').textContent = '★ '.repeat(Math.round(p.rating)) + ' ' + p.rating.toFixed(1) + '/5';
  document.getElementById('pdOldPrice').textContent = p.oldPrice ? fmt(p.oldPrice) : '';
  document.getElementById('pdPrice').textContent = fmt(p.price);
  document.getElementById('pdDesc').textContent = p.desc;
  document.getElementById('pdStock').textContent = p.stock>0 ? `${p.stock} em estoque` : 'Produto esgotado';
  document.getElementById('pdGallery').innerHTML = p.photo
    ? `<img src="${p.photo}" alt="${p.name}" style="width:100%;max-width:320px;margin:0 auto;display:block;object-fit:contain;">`
    : `<div class="spool">${spoolSVG(COLORS[currentColor],220)}</div>`;

  const swatchWrap = document.getElementById('pdSwatches');
  if(p.photo){
    // cor única já definida pela foto do produto — sem seletor de troca
    swatchWrap.parentElement.style.display = 'none';
  } else {
    swatchWrap.parentElement.style.display = '';
    swatchWrap.innerHTML = p.colors.map(c=>
      `<div class="swatch ${c===currentColor?'selected':''}" data-color="${c}" style="background:${COLORS[c]}" title="${c}"></div>`
    ).join('');
    document.querySelectorAll('#pdSwatches .swatch').forEach(sw=>{
      sw.addEventListener('click',()=>{
        currentColor = sw.dataset.color;
        document.querySelectorAll('#pdSwatches .swatch').forEach(s=>s.classList.remove('selected'));
        sw.classList.add('selected');
        document.getElementById('pdGallery').innerHTML = `<div class="spool">${spoolSVG(COLORS[currentColor],220)}</div>`;
      });
    });
  }

  document.getElementById('qtyVal').textContent = currentQty;
  document.getElementById('specTable').innerHTML = `
    <tr><td>Tipo de filamento</td><td>${p.type.toUpperCase()}</td></tr>
    <tr><td>Peso</td><td>${p.weight}</td></tr>
    <tr><td>Diâmetro</td><td>${p.diameter}</td></tr>
    <tr><td>Temperatura recomendada</td><td>${p.temp}</td></tr>
    <tr><td>Marca</td><td>${p.brand}</td></tr>
    <tr><td>Disponibilidade</td><td>${p.stock>0 ? 'Em estoque' : 'Esgotado'}</td></tr>
  `;
  document.getElementById('cepResult').textContent = '';
  document.getElementById('cepInput').value = '';
}

/* ================= RENDER: cart ================= */
function renderCart(){
  const empty = document.getElementById('cartEmpty');
  const full = document.getElementById('cartFull');
  if(cart.length===0){ empty.style.display='block'; full.style.display='none'; return; }
  empty.style.display='none'; full.style.display='grid';

  const list = document.getElementById('cartItemsList');
  list.innerHTML = cart.map((item,idx)=>{
    const p = PRODUCTS.find(x=>x.id===item.id);
    const hex = COLORS[item.color] || '#8a8f89';
    const thumb = p.photo
      ? `<img src="${p.photo}" alt="${p.name}" style="width:100%;height:100%;object-fit:contain;">`
      : `<div class="spool">${spoolSVG(hex)}</div>`;
    return `<div class="cart-item">
      ${thumb}
      <div>
        <div class="cart-item-name">${p.name}</div>
        <div class="cart-item-meta">${p.weight}</div>
        <div class="cart-item-price mono">${fmt(p.price)}</div>
        <div class="cart-remove" data-idx="${idx}">Remover</div>
      </div>
      <div class="cart-item-actions">
        <div class="qty-box">
          <button class="cart-minus" data-idx="${idx}">−</button>
          <span class="mono">${item.qty}</span>
          <button class="cart-plus" data-idx="${idx}">+</button>
        </div>
      </div>
    </div>`;
  }).join('');

  list.querySelectorAll('.cart-remove').forEach(el=>el.addEventListener('click',()=>{
    cart.splice(+el.dataset.idx,1); saveCart(); renderCart();
  }));
  list.querySelectorAll('.cart-plus').forEach(el=>el.addEventListener('click',()=>{
    cart[+el.dataset.idx].qty++; saveCart(); renderCart();
  }));
  list.querySelectorAll('.cart-minus').forEach(el=>el.addEventListener('click',()=>{
    const i=+el.dataset.idx; cart[i].qty--; if(cart[i].qty<=0) cart.splice(i,1); saveCart(); renderCart();
  }));

  const subtotal = cart.reduce((s,item)=>{
    const p = PRODUCTS.find(x=>x.id===item.id);
    return s + p.price*item.qty;
  },0);
  document.getElementById('sumSubtotal').textContent = fmt(subtotal);
  document.getElementById('sumTotal').textContent = fmt(subtotal);
}

/* ================= CART LOGIC ================= */
function addToCart(p, color, qty){
  const existing = cart.find(i=>i.id===p.id && i.color===color);
  if(existing){ existing.qty += qty; } else { cart.push({id:p.id, color, qty}); }
  saveCart();
  showToast(`${p.name} adicionado ao carrinho`);
}

function showToast(msg){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(window._toastTimer);
  window._toastTimer = setTimeout(()=>t.classList.remove('show'), 2400);
}

