/* ================= ROUTER ================= */
let navHistory = [];
function goBack(){
  navHistory.pop(); // remove current page
  const prev = navHistory.pop(); // get previous page
  location.hash = prev || '#home';
}

function router(){
  const hash = location.hash || '#home';
  const hashNoQuery = hash.split('?')[0];
  const [route, param] = hashNoQuery.replace('#','').split('/');
  document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));
  document.querySelectorAll('[data-nav]').forEach(a=>a.classList.remove('active'));

  const viewMap = {
    home:'view-home', produtos:'view-produtos', produto:'view-produto',
    carrinho:'view-carrinho', quemsomos:'view-quemsomos', tipos:'view-tipos',
    faq:'view-faq', ofertas:'view-ofertas', pagamento:'view-pagamento',
    envio:'view-envio', troca:'view-troca', contato:'view-contato',
    'pedido-confirmado':'view-pedido-confirmado', admin:'view-admin'
  };

  if(route==='admin' && !isAdmin()){
    showToast('Acesso restrito ao administrador.');
    location.hash = '#home';
    return;
  }

  const viewId = viewMap[route] || 'view-home';
  document.getElementById(viewId).classList.add('active');

  if(route==='produtos') renderAllProducts(param);
  if(route==='produto') renderProductDetail(param);
  if(route==='carrinho') renderCart();
  if(route==='ofertas') renderOfertas();
  if(route==='admin') renderAdminProducts();
  if(route==='pedido-confirmado'){
    const params = new URLSearchParams(hash.split('?')[1] || '');
    const ref = params.get('reference_id') || localStorage.getItem('elo3d_last_order') || '';
    document.getElementById('orderRefDisplay').textContent = ref ? `Pedido nº ${ref}` : '';
    cart = [];
    saveCart();
  }

  // registra a navegação pra permitir o botão "Voltar" funcionar entre abas
  if(navHistory[navHistory.length-1] !== hash){
    navHistory.push(hash);
    if(navHistory.length > 30) navHistory.shift();
  }

  window.scrollTo({top:0,behavior:'instant'});
  closeDrawer();
}
window.addEventListener('hashchange', router);

