document.getElementById('checkoutBtn').addEventListener('click', async ()=>{
  if(cart.length === 0){ showToast('Seu carrinho está vazio'); return; }

  if(!currentUser){
    showToast('Você precisa entrar ou criar uma conta pra finalizar a compra');
    openAccountModal();
    // depois de logar/cadastrar com sucesso, volta e finaliza a compra sozinho
    pendingCheckoutAfterLogin = true;
    return;
  }

  const items = cart.map(item=>{
    const p = PRODUCTS.find(x=>x.id===item.id);
    return { name: p.name, qty: item.qty, price: p.price };
  });

  const btn = document.getElementById('checkoutBtn');
  const originalText = btn.textContent;
  btn.textContent = 'Preparando pagamento...';
  btn.disabled = true;

  try{
    const res = await fetch('/.netlify/functions/create-checkout', {
      method: 'POST',
      headers: {'Content-Type':'application/json'},
      body: JSON.stringify({ items, siteUrl: window.location.origin })
    });
    const data = await res.json();
    if(!res.ok || !data.checkoutUrl){
      console.error('Erro checkout:', data);
      showToast('Erro ao iniciar pagamento. Tenta de novo.');
      btn.textContent = originalText;
      btn.disabled = false;
      return;
    }
    if(data.referenceId){ localStorage.setItem('elo3d_last_order', data.referenceId); }
    window.location.href = data.checkoutUrl;
  } catch(err){
    console.error(err);
    showToast('Erro de conexão. Tenta de novo.');
    btn.textContent = originalText;
    btn.disabled = false;
  }
});

/* ================= ACCOUNT (Firebase Auth + Firestore) ================= */
let currentUser = null; // { uid, name, email, celular, cpf }
let pendingCheckoutAfterLogin = false;

function onLoginSuccess(){
  closeAccountModal();
  if(pendingCheckoutAfterLogin){
    pendingCheckoutAfterLogin = false;
    document.getElementById('checkoutBtn').click();
  }
}

function requireFirebase(){
  if(!firebaseReady){
    showToast('Firebase ainda não configurado — fala com quem administra o site.');
    return false;
  }
  return true;
}

function openAccountModal(){
  renderAccountModal();
  document.getElementById('accountOverlay').classList.add('open');
}
function closeAccountModal(){
  document.getElementById('accountOverlay').classList.remove('open');
}
function renderAccountModal(){
  const loggedOut = document.getElementById('accountLoggedOut');
  const loggedIn = document.getElementById('accountLoggedIn');
  if(currentUser){
    loggedOut.style.display='none';
    loggedIn.classList.add('active');
    document.getElementById('accountName').textContent = currentUser.name || currentUser.email;
    document.getElementById('accountEmail').textContent = currentUser.email;
    document.getElementById('accountInitial').textContent = (currentUser.name||currentUser.email).charAt(0).toUpperCase();
  } else {
    loggedOut.style.display='block';
    loggedIn.classList.remove('active');
  }
}

document.getElementById('accountBtn').addEventListener('click', openAccountModal);
document.getElementById('modalClose').addEventListener('click', closeAccountModal);
document.getElementById('accountOverlay').addEventListener('click', (e)=>{
  if(e.target.id==='accountOverlay') closeAccountModal();
});

document.querySelectorAll('.modal-tab').forEach(tab=>{
  tab.addEventListener('click', ()=>{
    document.querySelectorAll('.modal-tab').forEach(t=>t.classList.remove('active'));
    document.querySelectorAll('.modal-form').forEach(f=>f.classList.remove('active'));
    tab.classList.add('active');
    document.querySelector(`.modal-form[data-form="${tab.dataset.tab}"]`).classList.add('active');
  });
});

// preenchimento automático de endereço a partir do CEP
document.getElementById('signupCep').addEventListener('blur', async ()=>{
  const cepInput = document.getElementById('signupCep');
  const cep = cepInput.value.replace(/\D/g,'');
  if(cep.length !== 8) return;
  try{
    const res = await fetch(`https://viacep.com.br/ws/${cep}/json/`);
    const data = await res.json();
    if(data.erro) return;
    const form = document.getElementById('cadastroForm');
    const inputs = form.querySelectorAll('input');
    document.getElementById('signupRua').value = data.logradouro || '';
    inputs[8].value = data.bairro || ''; // bairro
    inputs[9].value = data.localidade || ''; // cidade
    inputs[10].value = data.uf || ''; // uf
  } catch(e){ console.error('Erro ao buscar CEP:', e); }
});

document.getElementById('cadastroForm').addEventListener('submit', async (e)=>{
  e.preventDefault();
  if(!requireFirebase()) return;
  const inputs = e.target.querySelectorAll('input');
  const [nome, email, celular, cpf, cep, rua, numero, complemento, bairro, cidade, uf, senha, confirmar] = Array.from(inputs).map(i=>i.value);
  if(senha !== confirmar){ showToast('As senhas não coincidem'); return; }
  const btn = e.target.querySelector('button[type="submit"]');
  btn.disabled = true; btn.textContent = 'Criando conta...';
  try{
    const cred = await fbAuth.createUserWithEmailAndPassword(email, senha);
    const uid = cred.user.uid;
    const profile = {
      name: nome, email, celular, cpf,
      endereco: { cep, rua, numero, complemento, bairro, cidade, uf },
      createdAt: firebase.firestore.FieldValue.serverTimestamp()
    };
    await fbDb.collection('customers').doc(uid).set(profile);
    currentUser = { uid, ...profile };
    showToast(`Conta criada! Bem-vindo(a), ${nome.split(' ')[0]}`);
    renderAccountModal();
    onLoginSuccess();
  } catch(err){
    console.error(err);
    const msgs = {
      'auth/email-already-in-use': 'Esse e-mail já tem uma conta.',
      'auth/weak-password': 'Senha muito fraca (mínimo 6 caracteres).',
      'auth/invalid-email': 'E-mail inválido.'
    };
    showToast(msgs[err.code] || 'Erro ao criar conta. Tenta de novo.');
  } finally {
    btn.disabled = false; btn.textContent = 'Criar conta';
  }
});

document.getElementById('loginForm').addEventListener('submit', async (e)=>{
  e.preventDefault();
  if(!requireFirebase()) return;
  const inputs = e.target.querySelectorAll('input');
  const [email, senha] = Array.from(inputs).map(i=>i.value);
  const btn = e.target.querySelector('button[type="submit"]');
  btn.disabled = true; btn.textContent = 'Entrando...';
  try{
    const cred = await fbAuth.signInWithEmailAndPassword(email, senha);
    const doc = await fbDb.collection('customers').doc(cred.user.uid).get();
    const profile = doc.exists ? doc.data() : {};
    currentUser = { uid: cred.user.uid, email, ...profile };
    showToast(`Bem-vindo(a) de volta, ${(currentUser.name||email).split(' ')[0]}`);
    renderAccountModal();
    onLoginSuccess();
  } catch(err){
    console.error(err);
    showToast('E-mail ou senha incorretos.');
  } finally {
    btn.disabled = false; btn.textContent = 'Entrar';
  }
});

document.getElementById('logoutBtn').addEventListener('click', async ()=>{
  if(firebaseReady){ try{ await fbAuth.signOut(); }catch(e){} }
  currentUser = null;
  renderAccountModal();
  showToast('Você saiu da conta');
});

// mantém o login mesmo se a pessoa fechar e voltar ao site
if(firebaseReady){
  fbAuth.onAuthStateChanged(async (user)=>{
    if(user){
      const doc = await fbDb.collection('customers').doc(user.uid).get();
      const profile = doc.exists ? doc.data() : {};
      currentUser = { uid: user.uid, email: user.email, ...profile };
    } else {
      currentUser = null;
    }
    updateAdminNavVisibility();
  });
}

