/* ================= ADMIN PANEL ================= */
function isAdmin(){
  return currentUser && ADMIN_EMAILS.includes(currentUser.email);
}

function updateAdminNavVisibility(){
  const show = isAdmin() ? 'block' : 'none';
  document.getElementById('adminNavLink').style.display = show;
  document.getElementById('adminNavLinkDesktop').style.display = show === 'block' ? 'inline' : 'none';
}

function fileToBase64(file){
  return new Promise((resolve, reject)=>{
    const reader = new FileReader();
    reader.onload = ()=> resolve(reader.result);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

document.querySelectorAll('[data-admintab]').forEach(tab=>{
  tab.addEventListener('click', ()=>{
    document.querySelectorAll('[data-admintab]').forEach(t=>t.classList.remove('active'));
    tab.classList.add('active');
    document.getElementById('adminProdutosTab').classList.toggle('active', tab.dataset.admintab==='produtos');
    document.getElementById('adminClientesTab').classList.toggle('active', tab.dataset.admintab==='clientes');
    if(tab.dataset.admintab==='clientes') renderAdminCustomers();
  });
});

function renderAdminProducts(){
  const wrap = document.getElementById('adminProductsList');
  if(!wrap) return;
  wrap.innerHTML = PRODUCTS.map(p=>`
    <div class="admin-row" data-id="${p.id}">
      <img src="${p.photo || ''}" alt="${p.name}">
      <div>
        <div class="a-type">${p.type}</div>
        <div class="a-name">${p.name}</div>
      </div>
      <input type="number" step="0.01" class="a-price" value="${p.price}" title="Preço">
      <input type="number" step="0.01" class="a-oldprice" value="${p.oldPrice||''}" title="Preço antigo" placeholder="sem oferta">
      <input type="file" class="a-file" accept="image/*">
      <button class="a-save">Salvar</button>
    </div>
  `).join('');

  wrap.querySelectorAll('.admin-row').forEach(row=>{
    row.querySelector('.a-save').addEventListener('click', async ()=>{
      if(!requireFirebase()) return;
      const id = row.dataset.id;
      const price = parseFloat(row.querySelector('.a-price').value) || 0;
      const oldPriceVal = row.querySelector('.a-oldprice').value;
      const oldPrice = oldPriceVal ? parseFloat(oldPriceVal) : null;
      const fileInput = row.querySelector('.a-file');
      const btn = row.querySelector('.a-save');
      btn.disabled = true; btn.textContent = 'Salvando...';
      try{
        const update = { price, oldPrice };
        if(fileInput.files && fileInput.files[0]){
          update.photo = await fileToBase64(fileInput.files[0]);
        }
        await fbDb.collection('products').doc(id).update(update);
        showToast('Produto atualizado!');
      } catch(e){
        console.error(e);
        showToast('Erro ao salvar. Tenta de novo.');
      } finally {
        btn.disabled = false; btn.textContent = 'Salvar';
      }
    });
  });
}

async function renderAdminCustomers(){
  const wrap = document.getElementById('adminCustomersList');
  if(!wrap || !firebaseReady) return;
  wrap.innerHTML = '<p style="color:var(--text-dim);">Carregando clientes...</p>';
  try{
    const snap = await fbDb.collection('customers').orderBy('createdAt','desc').get();
    if(snap.empty){
      wrap.innerHTML = '<p style="color:var(--text-dim);">Nenhum cliente cadastrado ainda.</p>';
      return;
    }
    wrap.innerHTML = snap.docs.map(doc=>{
      const c = doc.data();
      return `<div class="customer-row">
        <div><span class="c-label">Nome</span>${c.name||'—'}</div>
        <div><span class="c-label">E-mail</span>${c.email||'—'}</div>
        <div><span class="c-label">Celular</span>${c.celular||'—'}</div>
        <div><span class="c-label">CPF</span>${c.cpf||'—'}</div>
      </div>`;
    }).join('');
  } catch(e){
    console.error(e);
    wrap.innerHTML = '<p style="color:var(--text-dim);">Erro ao carregar clientes.</p>';
  }
}

